// Conformance vectors: spec/testvectors/vectors.json is generated by this
// file (go test ./internal/lmbp -run TestVectors -update) and then verified
// against the reference implementation. Other languages consume the same file.

var update = flag.Bool("update", false, "rewrite spec/testvectors/vectors.json")

const vecIat = int64(1767225600) // 2026-01-01T00:00:00Z

const vecIssuer = "https://gw.example.com"

type vecKey struct {
	Seed               string `json:"seed_b64url"`
	Public             string `json:"public_b64url"`
	JWK                JWK    `json:"jwk"`
	JKT                string `json:"jkt"`
	JWKThumbprintInput string `json:"jwk_thumbprint_input"`
}

type vecJWS struct {
	Name            string          `json:"name"`
	Kind            string          `json:"kind"`
	SignedBy        string          `json:"signed_by"`
	ProtectedHeader json.RawMessage `json:"protected_header"`
	HeaderB64       string          `json:"protected_b64url"`
	Payload         json.RawMessage `json:"payload"`
	PayloadB64      string          `json:"payload_b64url"`
	SigningInput    string          `json:"signing_input"`
	Signature       string          `json:"signature_b64url"`
	Compact         string          `json:"compact"`
	Expect          map[string]any  `json:"verify_with"`
}

type vecNeg struct {
	Name     string         `json:"name"`
	Kind     string         `json:"kind"`
	Compact  string         `json:"compact"`
	VerifyBy string         `json:"verify_with_key"`
	Expect   map[string]any `json:"verify_with"`
	Why      string         `json:"must_reject_because"`
}

type vecFrame struct {
	Name  string          `json:"name"`
	Frame json.RawMessage `json:"frame"`
	Why   string          `json:"must_reject_because,omitempty"`
}

type vectors struct {
	Description string              `json:"description"`
	Now         int64               `json:"now"`
	Keys        map[string]vecKey   `json:"keys"`
	Base64URL   []map[string]string `json:"base64url"`
	Ath         []map[string]string `json:"ath"`
	JWS         []vecJWS            `json:"jws"`
	Negative    []vecNeg            `json:"negative"`
	ValidFrames []vecFrame          `json:"valid_frames"`
	BadFrames   []vecFrame          `json:"invalid_frames"`
	E2EE        *vecE2EE            `json:"e2ee"`
	Flow        []vecFlow           `json:"flow"`
	Resume      []vecResume         `json:"resume"`
	Identity    *vecIdentity        `json:"identity"`
}

func vkey(label string) (ed25519.PrivateKey, vecKey) {
	seed := sha256.Sum256([]byte(label))
	k := ed25519.NewKeyFromSeed(seed[:])
	pub := k.Public().(ed25519.PublicKey)
	return k, vecKey{Seed: B64(seed[:]), Public: B64(pub), JWK: PublicJWK(pub), JKT: Thumbprint(pub),
		JWKThumbprintInput: `{"crv":"Ed25519","kty":"OKP","x":"` + B64(pub) + `"}`}
}

func mkJWS(name, kind, by string, key ed25519.PrivateKey, typ, kid string, payload any, expect map[string]any) vecJWS {
	p, _ := json.Marshal(payload)
	c := SignJWS(key, typ, kid, p)
	parts := strings.Split(c, ".")
	h, _ := UnB64(parts[0])
	return vecJWS{Name: name, Kind: kind, SignedBy: by, ProtectedHeader: h, HeaderB64: parts[0], Payload: p, PayloadB64: parts[1],
		SigningInput: parts[0] + "." + parts[1], Signature: parts[2], Compact: c, Expect: expect}
}

func rawJWS(key ed25519.PrivateKey, header string, payload []byte) string {
	in := B64([]byte(header)) + "." + B64(payload)
	return in + "." + B64(ed25519.Sign(key, []byte(in)))
}

